function primes_up_to(limit)
{
    let t0 = clock_ns()
    let is_prime = replicate([true], limit + 1)
    is_prime[0] = false
    is_prime[1] = false

    let t1 = clock_ns()
    let candidate = 2
    while (candidate * candidate <= limit) {
        if (is_prime[candidate]) {
            fill(is_prime, false, iter(candidate * candidate, candidate, limit + 1))
        }
        candidate = candidate + 1
    }

    let t2 = clock_ns()
    let result = count(is_prime, true)
    let t3 = clock_ns()
    return [t1 - t0, t2 - t1, t3 - t2, result]
}

let totals = [0, 0, 0]
var result = 0
for (let repetition in 0 to 300) {
 let phases = primes_up_to(20000)
 for (let i in 0 to 3) { totals[i] = totals[i] + phases[i] }
 result = result + phases[3]
}
print(result)
print(totals[0])
print(totals[1])
